export const UserList = () => {
    const[users, setUsers] = useState({})
    const{currentUser, setCurrentUser} =useContext(usernameContext)
    const buttonState = ['Add Friend', 'Pending', 'Confirm', 'View Profile']
    const [selectedUser, setSelectedUser] = useState('')
const displayAllUsers = async () => {
    try{
    const userList = await axios.get('/chatUsers/allUsers/')

    setUsers(userList.data)
    console.log(userList.data);

    }
      catch (err) {
            console.log(err);

        }
}

const handleButtonClick = async (state, user) =>{
try{
    console.log(user);
      console.log(currentUser);

if(state === buttonState[0]){
  const addUser = await axios.put(`/chatUsers/friendRequests/${currentUser}/${user}`)
  console.log(addUser);

}else if(state === buttonState[2]){
  const confirmUser = await axios.put(`/addFriend/${currentUser}/${user}`)
  console.log(confirmUser);

}



  displayAllUsers()
}
  catch (err) {
            console.log(err);

        }

}





  useEffect(()=>{
    displayAllUsers()

  },[])


  return (
<>
    {                    Array.isArray(users) ? 

users.map((u)=>{
const button = u.friends.hasOwnProperty(u.email)
